        /// <param name="minDurationMs">MinDurationMs keeps only traces that lasted at least this many milliseconds. Zero or absent keeps every trace in the window. (optional)</param>
        /// <returns>O11yTracesOut</returns>
        O11yTracesOut GetO11yTraces(long? range = default, long? limit = default, long? minDurationMs = default);

