        /// <param name="cancellationToken">Cancellation Token to cancel the request.</param>
        /// <returns>Task of void</returns>
        System.Threading.Tasks.Task PostO11yAlertsByReceiverAsync(string receiver, System.Threading.CancellationToken cancellationToken = default);

